'use strict';

// =============================================================
// SEED — 11 faixas anatômicas
// =============================================================
// ═══ Z DAS 11 FAIXAS ═══
const Z_BROCA       = -200;  // saída textual
const Z_MOTORA      = -150;  // comandos
