    // Conexão bidirecional com Self-Core (puxa identidade)
    v112_edge(V112.self_core_id, n.id, 0.5, {tipo: 'gramatica'});
    v112_edge(n.id, V112.self_core_id, 0.5, {tipo: 'gramatica'});
